function check(input, actual, expected) {
  const [target, n] = input;
  if (!Array.isArray(actual) || actual.length > 2 * n) return false;
  const stack = [];
  let next = 1;
  const matches = () => stack.length === target.length && stack.every((v, i) => v === target[i]);
  for (const op of actual) {
    // Once the stack equals target, no more operations are allowed.
    if (matches()) return false;
    if (op === 'Push') {
      if (next > n) return false;
      stack.push(next++);
    } else if (op === 'Pop') {
      if (!stack.length) return false;
      stack.pop();
    } else return false;
  }
  return matches();
}

