function validate([target, n]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (target.length < 1 || target.length > 100) return 'target needs 1 to 100 values.';
  if (target.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each target value is between 1 and n.';
  for (let i = 1; i < target.length; i++) if (target[i] <= target[i - 1]) return 'target must be strictly increasing.';
  return null;
}

