function buildArray(target, n) {
  // A different valid answer: push a whole run of unwanted numbers, then pop them all at once.
  const ops = [];
  let next = 1;
  for (const want of target) {
    let extra = 0;
    while (next < want) { ops.push('Push'); next++; extra++; }
    for (let k = 0; k < extra; k++) ops.push('Pop');
    ops.push('Push');
    next++;
  }
  return ops;
}

