function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const keep = rand();
  let target = [];
  for (let v = 1; v <= n; v++) if (rand() < keep) target.push(v);
  if (!target.length) target = [1 + Math.floor(rand() * n)];
  return [target, n];
}
